create or replace function public.get_client_job_staffing_rc1(p_job_id uuid)
returns jsonb language plpgsql stable security definer set search_path=public set row_security=off as $$
declare v_client uuid;v_job public.marketplace_jobs;begin
 select id into v_client from public.clients where user_id=auth.uid();if v_client is null then raise exception 'CLIENT_WORKSPACE_REQUIRED' using errcode='42501';end if;
 select * into v_job from public.marketplace_jobs where id=p_job_id and client_id=v_client;if v_job.id is null then raise exception 'JOB_NOT_OWNED_BY_CLIENT' using errcode='42501';end if;
 return jsonb_build_object('job_id',v_job.id,'required_guards',greatest(1,coalesce(v_job.required_guards,1)),'filled_slots',(select count(*) from public.job_guard_slots where job_id=v_job.id and guard_id is not null and status<>'cancelled'),'accepted_slots',(select count(*) from public.job_guard_slots where job_id=v_job.id and status in('accepted','en_route','active','completed')),'en_route_slots',(select count(*) from public.job_guard_slots where job_id=v_job.id and status='en_route'),'active_slots',(select count(*) from public.job_guard_slots where job_id=v_job.id and status='active'),'completed_slots',(select count(*) from public.job_guard_slots where job_id=v_job.id and status='completed'),'slots',coalesce((select jsonb_agg(jsonb_build_object('slot_number',s.slot_number,'status',s.status,'guard_name',case when s.guard_id is null then null else p.full_name end) order by s.slot_number) from public.job_guard_slots s left join public.guards g on g.id=s.guard_id left join public.profiles p on p.id=g.user_id where s.job_id=v_job.id),'[]'::jsonb));
end $$;
revoke all on function public.get_client_job_staffing_rc1(uuid) from public,anon;grant execute on function public.get_client_job_staffing_rc1(uuid) to authenticated,service_role;
